const items = $input.all();
const data = items[0].json;
const papers = data.data || [];
const minCitations = $('Webhook').item.json.body.minCitations || 0;
const minYear = $('Webhook').item.json.body.minYear || 2015;

// Filter by relevance criteria
const filtered = papers.filter(p => 
  (p.citationCount || 0) >= minCitations &&
  (p.year || 0) >= minYear &&
  p.abstract && p.abstract.length > 50
);

// Sort by citation count
filtered.sort((a, b) => (b.citationCount || 0) - (a.citationCount || 0));

return filtered.map(p => ({
  json: {
    title: p.title,
    abstract: p.abstract,
    year: p.year,
    citations: p.citationCount || 0,
    authors: (p.authors || []).map(a => a.name).join(', '),
    venue: p.venue || '',
    url: p.url || '',
    doi: p.externalIds ? p.externalIds.DOI || '' : ''
  }
}));

